const fs = require("fs");
const path = require("path");

const ROOT =
  process.cwd();

const PAYLOADS =
  {"lib/research/get-forward-oos-observability-dashboard-v1.ts": "", "scripts/forward-oos-observability-dashboard-v1-contract-test.ts": "", "scripts/forward-oos-observability-dashboard-v1-static-verify.cjs": ""};

const BACKUP =
  path.join(
    ROOT,
    "scripts",
    "backups"
  );

function fail(
  reason,
  extra = {}
) {
  console.error(JSON.stringify({
    status:
      "AI_STOCK_LAB_FORWARD_OOS_OBSERVABILITY_DASHBOARD_BUILD_HYGIENE_V2_FAILED",
    reason,
    ...extra
  }, null, 2));

  process.exitCode = 1;
}

function writePayload(
  rel,
  payload
) {
  const target =
    path.join(
      ROOT,
      rel
    );

  fs.mkdirSync(
    path.dirname(
      target
    ),
    {
      recursive:
        true
    }
  );

  fs.writeFileSync(
    target,
    Buffer.from(
      payload,
      "base64"
    ).toString(
      "utf8"
    ),
    "utf8"
  );
}

const paperFile =
  path.join(
    ROOT,
    "lib",
    "trading",
    "execute-paper-order.ts"
  );

if (
  !fs.existsSync(
    paperFile
  )
) {
  fail(
    "EXECUTE_PAPER_ORDER_SOURCE_NOT_FOUND"
  );
} else {
  fs.mkdirSync(
    BACKUP,
    {
      recursive:
        true
    }
  );

  const paperBackup =
    path.join(
      BACKUP,
      "execute-paper-order.before-dashboard-build-hygiene-v2.ts"
    );

  if (
    !fs.existsSync(
      paperBackup
    )
  ) {
    fs.copyFileSync(
      paperFile,
      paperBackup
    );
  }

  const serviceFile =
    path.join(
      ROOT,
      "lib",
      "research",
      "get-forward-oos-observability-dashboard-v1.ts"
    );

  if (
    fs.existsSync(
      serviceFile
    )
  ) {
    const serviceBackup =
      path.join(
        BACKUP,
        "get-forward-oos-observability-dashboard-v1.before-build-hygiene-v2.ts"
      );

    if (
      !fs.existsSync(
        serviceBackup
      )
    ) {
      fs.copyFileSync(
        serviceFile,
        serviceBackup
      );
    }
  }

  for (
    const [
      rel,
      payload
    ] of Object.entries(
      PAYLOADS
    )
  ) {
    writePayload(
      rel,
      payload
    );
  }

  let paper =
    fs.readFileSync(
      paperFile,
      "utf8"
    );

  const alreadyFixed =
    paper.includes(
      "orderData as unknown as"
    ) &&
    paper.includes(
      "PaperOrderExecutionRecord"
    );

  if (
    !alreadyFixed
  ) {
    const pattern =
      /orderData\s+as\s+PaperOrderExecutionRecord;/g;

    const matches =
      [
        ...paper.matchAll(
          pattern
        )
      ];

    if (
      matches.length !==
      1
    ) {
      fail(
        "PAPER_ORDER_TYPE_CAST_PATTERN_NOT_UNIQUE",
        {
          matches:
            matches.length
        }
      );

      return;
    }

    paper =
      paper.replace(
        pattern,
        "orderData as unknown as\n      PaperOrderExecutionRecord;"
      );

    fs.writeFileSync(
      paperFile,
      paper,
      "utf8"
    );
  }

  const installedService =
    fs.readFileSync(
      path.join(
        ROOT,
        "lib",
        "research",
        "get-forward-oos-observability-dashboard-v1.ts"
      ),
      "utf8"
    );

  const installedPaper =
    fs.readFileSync(
      paperFile,
      "utf8"
    );

  const checks = {
    serviceV2Installed:
      installedService.includes(
        'import "server-only";'
      ),

    logsScopeInstalled:
      installedService.includes(
        '"logs",'
      ) &&
      !installedService.includes(
        "function full("
      ),

    staleGuardInstalled:
      installedService.includes(
        "Stale evaluator/summary readiness is suppressed"
      ),

    nullRateGuardInstalled:
      installedService.includes(
        "value === null"
      ),

    paperTypeOnlyBridgeInstalled:
      installedPaper.includes(
        "orderData as unknown as"
      ) &&
      installedPaper.includes(
        "PaperOrderExecutionRecord"
      ),

    alphaChanged:
      false,

    producerChanged:
      false,

    collectorChanged:
      false,

    paperRuntimeLogicChanged:
      false
  };

  const failed =
    Object.entries(
      checks
    )
      .filter(
        ([key, value]) =>
          ![
            "alphaChanged",
            "producerChanged",
            "collectorChanged",
            "paperRuntimeLogicChanged"
          ].includes(
            key
          ) &&
          value !== true
      )
      .map(
        ([key]) =>
          key
      );

  console.log(JSON.stringify({
    status:
      failed.length === 0
        ? "AI_STOCK_LAB_FORWARD_OOS_OBSERVABILITY_DASHBOARD_BUILD_HYGIENE_V2_REPAIRED"
        : "AI_STOCK_LAB_FORWARD_OOS_OBSERVABILITY_DASHBOARD_BUILD_HYGIENE_V2_FAILED",

    changedFiles: [
      "lib/research/get-forward-oos-observability-dashboard-v1.ts",
      "scripts/forward-oos-observability-dashboard-v1-contract-test.ts",
      "scripts/forward-oos-observability-dashboard-v1-static-verify.cjs",
      "lib/trading/execute-paper-order.ts"
    ],

    repair: {
      turbopack:
        "LOG_FILES_STATISTICALLY_SCOPED_UNDER_LOGS_DIRECTORY",

      staleForwardEvidence:
        "SUPPRESS_SUMMARY_READY_AND_RATES_UNTIL_REAL_OBSERVATIONS_EXIST",

      nullMetricSemantics:
        "NULL_UNDEFINED_EMPTY_NO_LONGER_COERCE_TO_ZERO",

      paperOrderBuildError:
        "TYPE_ONLY_UNKNOWN_BRIDGE_AS_RECOMMENDED_BY_TYPESCRIPT",

      paperRuntimeBehavior:
        "UNCHANGED"
    },

    checks,

    safety: {
      producerExecuted:
        false,

      collectorExecuted:
        false,

      databaseWrites:
        0,

      ordersCreated:
        0,

      positionsChanged:
        0,

      promotionExecuted:
        false,

      realTradingEnabled:
        false
    },

    failed,

    nextAction:
      failed.length === 0
        ? "RUN_STATIC_CONTRACT_AND_NEXT_BUILD"
        : "INSPECT_BUILD_HYGIENE_V2"
  }, null, 2));

  process.exitCode =
    failed.length === 0
      ? 0
      : 1;
}
